  CUSTOM_ROLES = (doc.custom_roles || []).map(r => typeof r === 'string' ? { name: r, pool: '' } : r).filter(r => r && r.name);
} catch (e) { CUSTOM_POOLS = []; CUSTOM_ROLES = []; }
